"""The task policy of the beaker-on-hotplate task: one source that owns the whole task in the controller's "auto" mode.

    policy = make_task_policy(model, data, task_cfg=TASK_CFG, staging_cfg=STAGING_CFG, arm_stage=None, points_fn=None)

A source is a dict whose "step"(obs) takes the observation dictionary (obs) that the control loop builds every tick and returns commands.
Two stages, in order:
  staging     src/staging_source.py (DRIVE -> PEDESTAL -> CORRECT_PEDESTAL -> ARMS -> CORRECT_ARMS -> NECK -> DONE), unchanged. It makes its own
              drift / clearance / pose-error measurements and reports them (policy["report"]()).
  arm stage   after staging (DONE = HANDOFF) the arm stage owns the arms and grippers; the base, pedestal and neck hold. An arm stage is a
              dict {"name", "step"(obs) -> command(s) or None, "state", optionally "resume"()}. Provided here:
                make_hold_stage()                      holds (nothing is commanded); used when arm_stage is None.
                make_request_operator_stage(reason)    asks for operator control once, then holds (so after the operator hands control
                                                       back the policy simply continues: holding).
              and, test only, src/episode_test_sources.make_cheat_arm_stage.

The controller (src/control_loop.py) steps the policy only in "auto" mode; in "teleop" mode it is paused, and resume() continues its current stage.
Rule for every policy: on resume, every subsystem starts from where the operator left it, and the policy then moves it toward what it wants; it never
jumps to a stale target. The staging stage does this for the base (its controllers slew from the applied Twist), the arm (src/rate_limit.py from the applied
targets, arm_max_speed), the gripper (the same, gripper_max_speed, after resume()), the pedestal (its phase ramps from the applied height) and the neck
(the loop slews it). A new policy or arm stage must do the same.

policy["status"]() -> {"stage": "STAGING" | the arm stage's name, "phase": the staging phase ("DONE" once staging is complete), "handoff": bool,
"error": the staging error or None}; the loop publishes it as obs["policy"].
"""

from src.staging_source import make_staging_source
from src.task_config import STAGING_CFG, TASK_CFG


def make_hold_stage():
    """Makes an arm stage that holds: it never commands anything.

    Returns:
        dict: An arm stage {"name": "hold", "step": step(obs) -> None, "state": {}}.
    """
    return {"name": "hold", "step": lambda obs: None, "state": {}}


def make_request_operator_stage(reason="manipulation is not implemented: operator control requested"):
    """Makes an arm stage that asks for operator control once and then holds.

    Args:
        reason (str): The text sent with the request, which the viewer shows to the operator. Defaults to
            "manipulation is not implemented: operator control requested".

    Returns:
        dict: An arm stage {"name": "request_operator", "step": step(obs) -> command or None, "state": state}. The first call
        to step returns {"mode": "request_teleop", "reason": reason}; every later call returns None. state["requested"] (bool)
        says whether the request has been sent.
    """
    state = {"requested": False}

    def step(obs):
        """Sends the operator request on the first call, then nothing.

        Args:
            obs (dict): The loop's observation. Not used.

        Returns:
            dict or None: {"mode": "request_teleop", "reason": reason} the first time, None afterwards.
        """
        if not state["requested"]:
            state["requested"] = True
            return {"mode": "request_teleop", "reason": reason}
        return None

    return {"name": "request_operator", "step": step, "state": state}


def make_task_policy(model, data, task_cfg=TASK_CFG, staging_cfg=STAGING_CFG, arm_stage=None, points_fn=None):
    """Makes the task policy: the staging stage first, then an arm stage.

    Args:
        model (mujoco.MjModel): The compiled model.
        data (mujoco.MjData): The simulation data.
        task_cfg (dict): The task configuration (poses and arm choice), see src/task_config.py. Defaults to TASK_CFG.
        staging_cfg (dict): The staging speeds, ramps and tolerances, see src/task_config.py. Defaults to STAGING_CFG.
        arm_stage (dict or None): The arm stage that takes over at the handoff: {"name", "step"(obs), "state", optionally
            "resume"()}. Defaults to None, which means make_hold_stage().
        points_fn (callable or None): points_fn(model, data, task_cfg) -> {name: world-frame (x, y, z) point in metres}, the points the neck
            camera must keep in view. Defaults to None, which uses the staging source's own default, framing_points().

    Returns:
        dict: The policy source, with the keys:
            "name" (str): "policy".
            "step" (callable): step(obs) -> list of commands. Runs the staging measurements every call; while staging is not
                done it returns the staging commands; afterwards it returns the commands that put back what the operator moved
                (if a restore is pending), then the arm stage's command (a dict, a list or None).
            "state" (dict): {"staging": the staging state dict, "arm": the arm stage's state}.
            "status" (callable): status() -> {"stage": "STAGING" until staging is done, then the arm stage's name, "phase": the
                staging phase ("DONE" once complete), "handoff" (bool): whether staging is done, "error": the staging error
                text or None}.
            "resume" (callable): resume() -> None. Called when the operator hands control back; resumes the staging source and,
                once staging is done, the arm stage (if it has a "resume" entry).
            "report" (callable): report() -> dict, the staging part of the episode summary (see make_staging_source()).
            "staging" (dict): The staging source, as made by make_staging_source().
            "arm_stage" (dict): The arm stage in use.
    """
    staging = make_staging_source(model, data, task_cfg, staging_cfg, **({"points_fn": points_fn} if points_fn else {}))
    arm = arm_stage or make_hold_stage()
    st = staging["state"]

    def status():
        """Describes where the policy is, for the loop to publish as obs["policy"].

        Returns:
            dict: "stage" (str): "STAGING" until staging is done, then the arm stage's name. "phase" (str): the staging phase,
            "DONE" once staging is done. "handoff" (bool): whether staging is done. "error" (str or None): the staging error.
        """
        done = st["done"]
        return {"stage": arm["name"] if done else "STAGING", "phase": "DONE" if done else st["phase"], "handoff": done, "error": st["error"]}

    def step(obs):
        """Gives the commands for one tick: the staging stage, then the restore step, then the arm stage.

        Always calls the staging source's observe(obs) first (its drift and clearance measurements). Once staging is done and a
        restore after a hand-back is pending, the restore commands (pedestal and neck) are returned until it has finished; the
        arm stage is not stepped meanwhile.

        Args:
            obs (dict): The loop's observation, with at least "time", "timestep", "steps_per_frame" and what the staging source reads.

        Returns:
            list or dict or None: The commands of the stage in charge: a list of command dicts from the staging source or the
            restore step, or whatever the arm stage's step returns (a command dict, a list or None).
        """
        staging["observe"](obs)
        if not st["done"]:
            return staging["step"](obs)
        if staging["restoring"]():                 # after a hand-back: put back what the operator moved (pedestal, neck) before the arm stage goes on
            cmds, finished = staging["restore_step"](obs, obs["time"], obs["timestep"] * obs["steps_per_frame"])
            if not finished:
                return cmds
        return arm["step"](obs)       # the first call is the tick after staging set DONE (the handoff tick)

    def resume():
        """Continues the current stage after the operator hands control back.

        Calls the staging source's resume(), and the arm stage's resume() if staging is done and the arm stage has one.
        """
        staging["resume"]()
        if st["done"] and "resume" in arm:
            arm["resume"]()

    return {"name": "policy", "step": step, "state": {"staging": st, "arm": arm["state"]}, "status": status, "resume": resume,
            "report": staging["report"], "staging": staging, "arm_stage": arm}
